import { createClient } from 'npm:@supabase/supabase-js@2.116.0'
const cors={"Access-Control-Allow-Origin":"*","Access-Control-Allow-Headers":"authorization, x-client-info, apikey, content-type","Access-Control-Allow-Methods":"POST,OPTIONS"}
Deno.serve(async(req)=>{if(req.method==='OPTIONS')return new Response('ok',{headers:cors});try{const auth=req.headers.get('Authorization');if(!auth)throw new Error('Unauthorized');const userClient=createClient(Deno.env.get('SUPABASE_URL')!,Deno.env.get('SUPABASE_PUBLISHABLE_KEY')!,{global:{headers:{Authorization:auth}}});const token=auth.replace(/^Bearer\s+/,'');const{data:{user},error}=await userClient.auth.getUser(token);if(error||!user)throw new Error('Unauthorized');const{conversation_id,body}=await req.json();if(typeof conversation_id!=='string'||typeof body!=='string'||body.trim().length<1||body.trim().length>4000)throw new Error('Invalid message');const admin=createClient(Deno.env.get('SUPABASE_URL')!,Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!);const{data:c}=await admin.from('conversations').select('id,user_a,user_b').eq('id',conversation_id).maybeSingle();if(!c||![c.user_a,c.user_b].includes(user.id))throw new Error('Conversation unavailable');const other=c.user_a===user.id?c.user_b:c.user_a;const{data:blocked}=await admin.from('blocks').select('id').or(`and(blocker_id.eq.${user.id},blocked_id.eq.${other}),and(blocker_id.eq.${other},blocked_id.eq.${user.id})`).limit(1);if(blocked?.length)throw new Error('Blocked');const{data:msg,error:me}=await admin.from('messages').insert({conversation_id,sender_id:user.id,body:body.trim()}).select('id,conversation_id,sender_id,body,created_at').single();if(me)throw me;return new Response(JSON.stringify({message:msg}),{headers:{...cors,'Content-Type':'application/json'}})}catch(e){return new Response(JSON.stringify({error:e instanceof Error?e.message:'Request failed'}),{status:400,headers:{...cors,'Content-Type':'application/json'}})}})
